async function calcularExcedente(empresaId, saldo, mes, ano, tipoContrato) {
  try {
    console.log("\u{1F50D} BancoHorasExcedentesService.calcularExcedente:", {
      empresaId,
      saldo,
      mes,
      ano,
      tipoContrato
    });
    if (!empresaId?.trim()) {
      throw new Error("ID da empresa \xE9 obrigat\xF3rio");
    }
    if (mes < 1 || mes > 12) {
      throw new Error("M\xEAs deve estar entre 1 e 12");
    }
    if (ano < 2020) {
      throw new Error("Ano deve ser maior ou igual a 2020");
    }
    const isHoras = typeof saldo === "string";
    const isNegativo = isHoras ? saldo.startsWith("-") : saldo < 0;
    if (!isNegativo) {
      console.log("\u2705 Saldo n\xE3o \xE9 negativo, excedente = 0");
      return {
        excedente: isHoras ? "0:00" : 0,
        valorExcedente: 0,
        taxaUtilizada: null,
        taxaEncontrada: false
      };
    }
    let excedente;
    let excedenteMagnitude;
    if (isHoras) {
      const saldoLimpo = saldo.substring(1);
      excedente = saldoLimpo;
      excedenteMagnitude = converterHorasParaMinutos(saldoLimpo) / 60;
    } else {
      excedente = Math.abs(saldo);
      excedenteMagnitude = excedente;
    }
    console.log("\u{1F4CA} Excedente calculado:", {
      excedente,
      excedenteMagnitude,
      tipo: isHoras ? "horas" : "tickets"
    });
    const taxa = await buscarTaxaMes(empresaId, mes, ano, tipoContrato);
    if (taxa === null) {
      const alerta = "Taxa n\xE3o encontrada para o per\xEDodo. Excedente n\xE3o pode ser calculado.";
      console.warn("\u26A0\uFE0F", alerta);
      return {
        excedente,
        valorExcedente: 0,
        taxaUtilizada: null,
        taxaEncontrada: false,
        alerta
      };
    }
    const valorExcedente2 = excedenteMagnitude * taxa;
    console.log("\u2705 Excedente calculado com sucesso:", {
      excedente,
      taxa,
      valorExcedente: `R$ ${valorExcedente2.toFixed(2)}`
    });
    return {
      excedente,
      valorExcedente: valorExcedente2,
      taxaUtilizada: taxa,
      taxaEncontrada: true
    };
  } catch (error) {
    console.error("\u274C Erro ao calcular excedente:", error);
    throw new Error(
      `Erro ao calcular excedente: ${error instanceof Error ? error.message : "Erro desconhecido"}`
    );
  }
}
