// src/services/bancoHorasObservacoesService.ts
init_clienteSupabaseServidor();
var BancoHorasObservacoesService = class {
  /** Observações manuais da empresa, com nome/e-mail de quem criou */
  async listarObservacoesManuais(empresaId, periodo) {
    let query = supabase.from("banco_horas_observacoes").select("*").eq("empresa_id", empresaId);
    if (periodo) {
      query = query.eq("mes", periodo.mes).eq("ano", periodo.ano);
    }
    const { data: observacoes, error } = await query.order("created_at", { ascending: false });
    if (error) {
      console.error("Erro ao buscar observa\xE7\xF5es manuais:", error.message);
      throw error;
    }
    const registros = observacoes || [];
    return await this.adicionarUsuarios(registros);
  }
  /** Observações dos reajustes ativos (com observação preenchida) da empresa */
  async listarObservacoesReajustes(empresaId, periodo) {
    let query = supabase.from("banco_horas_reajustes").select("id, mes, ano, observacao, tipo_reajuste, valor_reajuste_horas, valor_reajuste_tickets, created_by, created_at").eq("empresa_id", empresaId).eq("ativo", true).not("observacao", "is", null).neq("observacao", "");
    if (periodo) {
      query = query.eq("mes", periodo.mes).eq("ano", periodo.ano);
    }
    const { data: reajustes, error } = await query.order("created_at", { ascending: false });
    if (error) {
      console.error("Erro ao buscar observa\xE7\xF5es de reajustes:", error.message);
      throw error;
    }
    const registros = reajustes || [];
    return await this.adicionarUsuarios(registros);
  }
  /** Une manuais e reajustes em uma lista única, da mais recente para a mais antiga */
  unificarObservacoes(manuais, reajustes) {
    return [
      ...manuais.map((obs) => ({
        id: obs.id,
        mes: obs.mes,
        ano: obs.ano,
        observacao: obs.observacao,
        tipo: "manual",
        created_by: obs.created_by,
        created_at: obs.created_at,
        updated_at: obs.updated_at,
        usuario_nome: obs.usuario_nome,
        usuario_email: obs.usuario_email
      })),
      ...reajustes.map((obs) => ({
        id: obs.id,
        mes: obs.mes,
        ano: obs.ano,
        observacao: obs.observacao,
        tipo: "ajuste",
        tipo_ajuste: obs.tipo_reajuste,
        valor_horas: obs.valor_reajuste_horas,
        valor_tickets: obs.valor_reajuste_tickets,
        created_by: obs.created_by,
        created_at: obs.created_at,
        usuario_nome: obs.usuario_nome,
        usuario_email: obs.usuario_email
      }))
    ].sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
  }
  /** Todas as observações (manuais + reajustes) da empresa, já unificadas */
  async listarObservacoesUnificadas(empresaId) {
    const [manuais, reajustes] = await Promise.all([
      this.listarObservacoesManuais(empresaId),
      this.listarObservacoesReajustes(empresaId)
    ]);
    return this.unificarObservacoes(manuais, reajustes);
  }
  /** Busca os perfis de quem criou cada registro (join manual) */
  async adicionarUsuarios(registros) {
    if (registros.length === 0) return [];
    const userIds = [...new Set(registros.map((r) => r.created_by).filter(Boolean))];
    if (userIds.length === 0) {
      return registros.map((r) => ({ ...r, usuario_nome: "Usu\xE1rio desconhecido", usuario_email: "" }));
    }
    const { data: profiles, error: profilesError } = await supabase.from("profiles").select("id, full_name, email").in("id", userIds);
    if (profilesError) {
      console.error("Erro ao buscar profiles:", profilesError.message);
    }
    const profilesMap = new Map((profiles || []).map((p) => [p.id, p]));
    return registros.map((r) => ({
      ...r,
      usuario_nome: profilesMap.get(r.created_by)?.full_name || "Usu\xE1rio desconhecido",
      usuario_email: profilesMap.get(r.created_by)?.email || ""
    }));
  }
};
var bancoHorasObservacoesService = new BancoHorasObservacoesService();

