function getOrdinal(n) {
  const suffixes = ["th", "st", "nd", "rd"];
  const v = n % 100;
  return n + (suffixes[(v - 20) % 10] || suffixes[v] || suffixes[0]);
}
function isEnglishTemplateByName(templateName) {
  if (!templateName) return false;
  const nameLower = templateName.toLowerCase();
  return nameLower.includes("english") || nameLower.includes("ingl\xEAs") || nameLower.includes("ingles") || nameLower.includes("ingles") || nameLower.includes("en ") || // "en " com espaço para evitar falsos positivos
  nameLower.startsWith("en") || // Começa com "en"
  nameLower.includes(" en") || // " en" precedido de espaço
  nameLower.includes("template en") || nameLower.includes("template ingl\xEAs") || nameLower.includes("template ingles") || nameLower.includes("template english");
}
function getLabels(isEnglish) {
  if (isEnglish === "es") return LABELS_ES;
  return isEnglish ? LABELS_EN : LABELS_PT;
}
function getPeriodName(periodoApuracao, numeroPeriodo, isEnglish) {
  const labels = getLabels(isEnglish);
  switch (periodoApuracao) {
    case 1:
      return labels.periodos.mensal;
    case 2:
      return labels.periodos.bimestre(numeroPeriodo);
    case 3:
      return labels.periodos.trimestre(numeroPeriodo);
    case 4:
      return labels.periodos.quadrimestre(numeroPeriodo);
    case 5:
      return labels.periodos.meses(5);
    case 6:
      return labels.periodos.semestre(numeroPeriodo);
    case 7:
      return labels.periodos.meses(7);
    case 8:
      return labels.periodos.meses(8);
    case 9:
      return labels.periodos.meses(9);
    case 10:
      return labels.periodos.meses(10);
    case 11:
      return labels.periodos.meses(11);
    case 12:
      return labels.periodos.anual;
    default:
      return labels.periodos.meses(periodoApuracao);
  }
}

// src/utils/periodoVigenciaUtils.ts
function calcularNomePeriodoComIdioma(inicioVigencia, periodoApuracao, mesAtual, anoAtual, isEnglish) {
  if (!inicioVigencia || !periodoApuracao) {
    if (isEnglish === "es") return "Per\xEDodo no definido";
    return isEnglish ? "Period not defined" : "Per\xEDodo n\xE3o definido";
  }
  let mesInicio;
  let anoInicio;
  try {
    if (inicioVigencia.includes("/")) {
      const [mes, ano] = inicioVigencia.split("/");
      mesInicio = parseInt(mes, 10);
      anoInicio = parseInt(ano, 10);
    } else if (inicioVigencia.includes("-")) {
      const data = new Date(inicioVigencia);
      mesInicio = data.getUTCMonth() + 1;
      anoInicio = data.getUTCFullYear();
    } else {
      const data = new Date(inicioVigencia);
      mesInicio = data.getUTCMonth() + 1;
      anoInicio = data.getUTCFullYear();
    }
  } catch (error) {
    console.error("Erro ao processar in\xEDcio da vig\xEAncia:", error);
    if (isEnglish === "es") return "Per\xEDodo inv\xE1lido";
    return isEnglish ? "Invalid period" : "Per\xEDodo inv\xE1lido";
  }
  const mesesPassados = (anoAtual - anoInicio) * 12 + (mesAtual - mesInicio);
  if (mesesPassados < 0) {
    if (isEnglish === "es") return "Vigencia no iniciada";
    return isEnglish ? "Validity not started" : "Vig\xEAncia n\xE3o iniciada";
  }
  const numeroPeriodo = Math.floor(mesesPassados / periodoApuracao) + 1;
  const periodosNoAno = Math.floor(12 / periodoApuracao);
  const periodoNoAno = (numeroPeriodo - 1) % periodosNoAno + 1;
  return getPeriodName(periodoApuracao, periodoNoAno, isEnglish);
}

